{"content": """"TileLang wrapper for SelectReduceMaxDSubExpReduceSumDRealDiv.

Calls the custom TileLang kernel defined in design/tile_level/.
"""

import torch
import torch.nn as nn

from design.tile_level.select_reduce_max_d_sub_exp_reduce_sum_d_real_div import (
    select_reduce_max_d_sub_exp_reduce_sum_d_real_div,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, sel: torch.Tensor, input1: torch.Tensor,
                input2: torch.Tensor) -> torch.Tensor:
        B, M, N = input1.shape
        dtype_str = "float16" if input1.dtype == torch.float16 else "float32"

        kernel = select_reduce_max_d_sub_exp_reduce_sum_d_real_div(B, M, N, dtype=dtype_str)
        output = kernel(sel, input1, input2)
        return output
