template <typename dataType>
class SelectReduceMaxDSubExpReduceSumDRealDivKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR sel, GM_ADDR input1, GM_ADDR input2, GM_ADDR output,
        GM_ADDR tiling)
    {
        // Copy tiling data
        AscendC::GlobalTensor<TilingData> tilingGM;
        tilingGM.SetGlobalBuffer(reinterpret_cast<__gm__ TilingData *>(tiling), 1);
        AscendC::DataCopy(tiling_, tilingGM, 1);
        AscendC::PipeBarrier<PIPE_ALL>();

        B_ = tiling_.B;
        M_ = tiling_.M;
        N_ = tiling_.N;
        totalRows_ = tiling_.totalRows;
        usedCoreNum_ = tiling_.usedCoreNum;
        tasksPerCore_ = tiling_.tasksPerCore;

        uint64_t totalElements = static_cast<uint64_t>(B_) * M_ * N_;

        selGM_.SetGlobalBuffer(reinterpret_cast<__gm__ uint8_t *>(sel), totalElements);
        input1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(input1), totalElements);
        input2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(input2), totalElements);
        outputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(output), totalElements);

        if ASCEND_IS_AIV {
            // UB buffer allocation
            // Input queues
            pipe_.InitBuffer(selQueue_, BUFFER_NUM, N_ * sizeof(uint8_t));
            pipe_.InitBuffer(input1Queue_, BUFFER_NUM, N_ * sizeof(dataType));
            pipe_.InitBuffer(input2Queue_, BUFFER_NUM, N_ * sizeof(dataType));
            // Output queue
            pipe_.InitBuffer(outputQueue_, BUFFER_NUM, N_ * sizeof(dataType));

            // Compute buffers (VECCALC)
            // For fp32 compute path
            pipe_.InitBuffer(fp32Buf_, N_ * sizeof(float));
            // For reduce tmp (2x element count, uint8)
            pipe_.InitBuffer(reduceTmpBuf_, 2 * N_ * sizeof(uint8_t));
            // For max/sum scalar results
            pipe_.InitBuffer(scalarBuf_, 16 * sizeof(float));

            if constexpr (!std::is_same_v<dataType, float>) {
                pipe_.InitBuffer(castBuf_, N_ * sizeof(float));
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
                int bx = coreIdx * tasksPerCore_ + localIdx;
                if (bx >= totalRows_) {
                    continue;
                }

                int bIdx = bx / M_;
                int mIdx = bx % M_;
                uint64_t rowOffset = static_cast<uint64_t>(bIdx) * M_ * N_ + static_cast<uint64_t>(mIdx) * N_;

                // CopyIn
                CopyIn(rowOffset);
                // Compute
                Compute();
                // CopyOut
                CopyOut(rowOffset);
            }
        }
    }

private:
    __aicore__ inline void CopyIn(uint64_t rowOffset)
    {
        selLocal_ = selQueue_.AllocTensor<uint8_t>();
        input1Local_ = input1Queue_.AllocTensor<dataType>();
        input2Local_ = input2Queue_.AllocTensor<dataType>();

        LoadGmToUb(selLocal_, selGM_[rowOffset], static_cast<uint32_t>(N_));
        LoadGmToUb(input1Local_, input1GM_[rowOffset], static_cast<uint32_t>(N_));
        LoadGmToUb(input2Local_, input2GM_[rowOffset], static_cast<uint32_t>(N_));

        selQueue_.EnQue(selLocal_);
        input1Queue_.EnQue(input1Local_);
        input2Queue_.EnQue(input2Local_);
    }

    __aicore__ inline void Compute()
    {
        // DeQue inputs
        selLocal_ = selQueue_.DeQue<uint8_t>();
        input1Local_ = input1Queue_.DeQue<dataType>();
        input2Local_ = input2Queue_.DeQue<dataType>();
        outputLocal_ = outputQueue_.AllocTensor<dataType>();

        // Get compute buffers
        fp32Local_ = fp32Buf_.Get<float>();
        reduceTmpLocal_ = reduceTmpBuf_.Get<uint8_t>();
        maxLocal_ = scalarBuf_.Get<float>();
        sumLocal_ = scalarBuf_.Get<float>();

        // Step 1: Cast inputs to fp32 (for numerical stability)
        if constexpr (std::is_same_v<dataType, float>) {
            // Select: out = input1 * sel + input2 * (1 - sel)
            // sel is bool (0 or 1), we use Select API
            // For float: reinterpret and use select
            AscendC::LocalTensor<float> in1Fp32 = input1Local_.template ReinterpretCast<float>();
            AscendC::LocalTensor<float> in2Fp32 = input2Local_.template ReinterpretCast<float>();

            // Use Select: selLocal_ as mask, pick from in1Fp32 or in2Fp32
            // sel is uint8 (0/1), we need to use it as comparison mask
            // First, create a float mask from sel
            AscendC::Cast(fp32Local_, selLocal_, AscendC::RoundMode::CAST_NONE, N_);
            // fp32Local_ now contains 0.0 or 1.0
            // out = in1 * mask + in2 * (1 - mask)
            // = in2 + (in1 - in2) * mask
            AscendC::Sub(fp32Local_, in1Fp32, in2Fp32, N_);
            AscendC::Mul(fp32Local_, fp32Local_, selLocal_.template ReinterpretCast<float>(), N_);
            AscendC::Add(fp32Local_, fp32Local_, in2Fp32, N_);
        } else {
            // Cast to fp32 first
            AscendC::LocalTensor<float> in1Fp32 = castBuf_.Get<float>();
            AscendC::LocalTensor<float> in2Fp32 = castBuf_.Get<float>();
            // Use different offset for in2Fp32 to avoid overlap
            // Actually castBuf_ is only N_ * sizeof(float), need to be careful
            // Let's use fp32Local_ as temp and reuse
            AscendC::Cast(fp32Local_, input1Local_, AscendC::RoundMode::CAST_NONE, N_);
            // Copy to a safe location - use maxLocal_ as temp storage
            AscendC::DataCopy(in1Fp32, fp32Local_, N_);
            AscendC::Cast(fp32Local_, input2Local_, AscendC::RoundMode::CAST_NONE, N_);
            AscendC::DataCopy(in2Fp32, fp32Local_, N_);

            // Now compute select in fp32
            // Cast sel to float mask
            AscendC::Cast(fp32Local_, selLocal_, AscendC::RoundMode::CAST_NONE, N_);
            // fp32Local_ = in1Fp32 - in2Fp32
            AscendC::Sub(fp32Local_, in1Fp32, in2Fp32, N_);
            // fp32Local_ = fp32Local_ * mask
            // Need mask as float - reuse in1Fp32 area after
            AscendC::LocalTensor<float> maskFp32 = castBuf_.Get<float>();
            AscendC::Cast(maskFp32, selLocal_, AscendC::RoundMode::CAST_NONE, N_);
            AscendC::Mul(fp32Local_, fp32Local_, maskFp32, N_);
            // fp32Local_ = fp32Local_ + in2Fp32
            AscendC::Add(fp32Local_, fp32Local_, in2Fp32, N_);
        }

        // Step 2: ReduceMax over N
        AscendC::ReduceMax<float>(maxLocal_, fp32Local_, reduceTmpLocal_, N_);
        AscendC::PipeBarrier<PIPE_ALL>();
        float maxVal = maxLocal_.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        // Step 3: Sub = fp32Local_ - maxVal
        AscendC::Adds(fp32Local_, fp32Local_, -maxVal, N_);

        // Step 4: Exp
        AscendC::Exp(fp32Local_, fp32Local_, N_);

        // Step 5: ReduceSum over N
        AscendC::ReduceSum<float>(sumLocal_, fp32Local_, reduceTmpLocal_, N_);
        AscendC::PipeBarrier<PIPE_ALL>();
        float sumVal = sumLocal_.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        // Step 6: Div = fp32Local_ / sumVal
        float invSum = 1.0f / sumVal;
        AscendC::Muls(fp32Local_, fp32Local_, invSum, N_);

        // Step 7: Cast back to original dtype and write to output
        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::LocalTensor<float> outFp32 = outputLocal_.template ReinterpretCast<float>();
            AscendC::DataCopy(outFp32, fp32Local_, N_);
        } else {
            AscendC::Cast(outputLocal_, fp32Local_, AscendC::RoundMode::CAST_ROUND, N_);
        }

        // Free inputs
        selQueue_.FreeTensor(selLocal_);
        input1Queue_.FreeTensor(input1Local_);
        input2Queue_.FreeTensor(input2Local_);
        // EnQue output
        outputQueue_.EnQue(outputLocal_);
    }

    __aicore__ inline void CopyOut(uint64_t rowOffset)
    {
        outputLocal_ = outputQueue_.DeQue<dataType>();
        StoreUbToGm(outputGM_[rowOffset], outputLocal_, static_cast<uint32_t>(N_));
        outputQueue_.FreeTensor(outputLocal_);
    }

private:
    int32_t B_ = 0;
    int32_t M_ = 0;
    int32_t N_ = 0;
    int32_t totalRows_ = 0;
    int32_t usedCoreNum_ = 0;
    int32_t tasksPerCore_ = 0;

    TilingData tiling_;
    AscendC::TPipe pipe_;

    AscendC::GlobalTensor<uint8_t> selGM_;
    AscendC::GlobalTensor<dataType> input1GM_;
    AscendC::GlobalTensor<dataType> input2GM_;
    AscendC::GlobalTensor<dataType> outputGM_;

    // Queues
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> selQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> input1Queue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> input2Queue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outputQueue_;

    // Buffers
    AscendC::TBuf<AscendC::TPosition::VECCALC> fp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> scalarBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;

    // Local tensors
    AscendC::LocalTensor<uint8_t> selLocal_;
    AscendC::LocalTensor<dataType> input1Local_;
    AscendC::LocalTensor<dataType> input2Local_;
    AscendC::LocalTensor<dataType> outputLocal_;
    AscendC::LocalTensor<float> fp32Local_;
    AscendC::LocalTensor<uint8_t> reduceTmpLocal_;
    AscendC::LocalTensor<float> maxLocal_;
