namespace ascend_kernel {

at::Tensor select_reduce_max_d_sub_exp_reduce_sum_d_real_div(
    const at::Tensor &sel,
    const at::Tensor &input1,
    const at::Tensor &input2)
{
    TORCH_CHECK(input1.dim() == 3, "input1 must be 3D [B, M, N]");
    TORCH_CHECK(input2.dim() == 3, "input2 must be 3D [B, M, N]");
    TORCH_CHECK(sel.dim() == 3, "sel must be 3D [B, M, N]");
    TORCH_CHECK(input1.sizes() == input2.sizes(), "input1 and input2 must have same shape");
    TORCH_CHECK(sel.sizes() == input1.sizes(), "sel must have same shape as inputs");
    TORCH_CHECK(
        input1.scalar_type() == at::kFloat || input1.scalar_type() == at::kHalf ||
            input1.scalar_type() == at::kBFloat16,
        "input1 must be float16, float32, or bfloat16");
    TORCH_CHECK(input2.scalar_type() == input1.scalar_type(),
        "input2 must have the same dtype as input1");
    TORCH_CHECK(sel.scalar_type() == at::kBool, "sel must be bool");
    TORCH_CHECK(input1.is_contiguous(), "input1 must be contiguous");
    TORCH_CHECK(input2.is_contiguous(), "input2 must be contiguous");
    TORCH_CHECK(sel.is_contiguous(), "sel must be contiguous");

    int32_t B = static_cast<int32_t>(input1.sizes()[0]);
    int32_t M = static_cast<int32_t>(input1.sizes()[1]);
    int32_t N = static_cast<int32_t>(input1.sizes()[2]);
    int32_t totalRows = B * M;

    auto output = at::empty_like(input1);

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (input1.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (input1.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // Platform info
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    int32_t usedCoreNum = static_cast<int32_t>(std::min<int64_t>(coreNum, totalRows));
    int32_t tasksPerCore = (totalRows + usedCoreNum - 1) / usedCoreNum;

    // Tiling data
    TilingData tiling;
    tiling.B = B;
    tiling.M = M;
    tiling.N = N;
    tiling.totalRows = totalRows;
    tiling.usedCoreNum = usedCoreNum;
    tiling.tasksPerCore = tasksPerCore;
    tiling.dtypeFlag = dtypeFlag;

    auto tilingTensor = at::empty(
        {static_cast<int64_t>(sizeof(TilingData))},
        at::TensorOptions().dtype(at::kByte).device(input1.device()));
    memcpy(tilingTensor.data_ptr(), &tiling, sizeof(TilingData));

    // All params must be left values
