    int64_t dtypeFlagVal = dtypeFlag;

    EXEC_KERNEL_CMD(select_reduce_max_d_sub_exp_reduce_sum_d_real_div, blockDim,
                    sel, input1, input2, output,
                    tilingTensor, dtypeFlagVal);

    return output;
}

