73	        AscendC::PipeBarrier<PIPE_ALL>();
74	
75	        B_ = tiling_.B;
76	        M_ = tiling_.M;
77	        N_ = tiling_.N;
78	        totalRows_ = tiling_.totalRows;
79	        usedCoreNum_ = tiling_.usedCoreNum;
80	        tasksPerCore_ = tiling_.tasksPerCore;
81	
82	        uint64_t totalElements = static_cast<uint64_t>(B_) * M_ * N_;
83	
84	        selGM_.SetGlobalBuffer(reinterpret_cast<__gm__ uint8_t *>(sel), totalElements);
85	        input1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(input1), totalElements);
86	        input2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(input2), totalElements);
87	        outputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(output), totalElements);
88	
89	        if ASCEND_IS_AIV {
90	            // UB buffer allocation
91	            // Input queues
92	            pipe_.InitBuffer(selQueue_, BUFFER_NUM, N_ * sizeof(uint8_t));
93	            pipe_.InitBuffer(input1Queue_, BUFFER_NUM, N_ * sizeof(dataType));
94	            pipe_.InitBuffer(input2Queue_, BUFFER_NUM, N_ * sizeof(dataType));
95	            // Output queue
96	            pipe_.InitBuffer(outputQueue_, BUFFER_NUM, N_ * sizeof(dataType));
97	
98	            // Compute buffers (VECCALC)
99	            // For fp32 compute path
100	            pipe_.InitBuffer(fp32Buf_, N_ * sizeof(float));
101	            // For reduce tmp (2x element count, uint8)
102	            pipe_.InitBuffer(reduceTmpBuf_, 2 * N_ * sizeof(uint8_t));
103	            // For max/sum scalar results
104	            pipe_.InitBuffer(scalarBuf_, 16 * sizeof(float));
105	
106	            if constexpr (!std::is_same_v<dataType, float>) {
107	                pipe_.InitBuffer(castBuf_, N_ * sizeof(float));
108	            }
109	        }
110	    }
111	
112	    __aicore__ inline void Process()
113	    {
114	        if ASCEND_IS_AIV {
115	            const int coreIdx = AscendC::GetBlockIdx();
116	
117	            for (int localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
118	                int bx = coreIdx * tasksPerCore_ + localIdx;
119	                if (bx >= totalRows_) {
120	                    continue;
121	                }
122	
123	                int bIdx = bx / M_;
124	                int mIdx = bx % M_;
125	                uint64_t rowOffset = static_cast<uint64_t>(bIdx) * M_ * N_ + static_cast<uint64_t>(mIdx) * N_;
126	
127	                // CopyIn
128	                CopyIn(rowOffset);
129	                // Compute
130	                Compute();
131	                // CopyOut
132	                CopyOut(rowOffset);
133	            }
134	        }
135	    }
136	
137	private:
138	    __aicore__ inline void CopyIn(uint64_t rowOffset)
139	    {
140	        selLocal_ = selQueue_.AllocTensor<uint8_t>();
141	        input1Local_ = input1Queue_.AllocTensor<dataType>();
142	        input2Local_ = input2Queue_.AllocTensor<dataType>();
143	
144	        LoadGmToUb(selLocal_, selGM_[rowOffset], static_cast<uint32_t>(N_));
145	        LoadGmToUb(input1Local_, input1GM_[rowOffset], static_cast<uint32_t>(N_));
146	        LoadGmToUb(input2Local_, input2GM_[rowOffset], static_cast<uint32_t>(N_));
147	
148	        selQueue_.EnQue(selLocal_);
149	        input1Queue_.EnQue(input1Local_);
150	        input2Queue_.EnQue(input2Local_);
151	    }
152	
153	    __aicore__ inline void Compute()
154	    {
155	        // DeQue inputs
156	        selLocal_ = selQueue_.DeQue<uint8_t>();
157	        input1Local_ = input1Queue_.DeQue<dataType>();
158	        input2Local_ = input2Queue_.DeQue<dataType>();
159	        outputLocal_ = outputQueue_.AllocTensor<dataType>();
160	
161	        // Get compute buffers
162	        fp32Local_ = fp32Buf_.Get<float>();
163	        reduceTmpLocal_ = reduceTmpBuf_.Get<uint8_t>();
164	        maxLocal_ = scalarBuf_.Get<float>();
165	        sumLocal_ = scalarBuf_.Get<float>();
166	
167	        // Step 1: Cast inputs to fp32 (for numerical stability)
168	        if constexpr (std::is_same_v<dataType, float>) {
169	            // Select: out = input1 * sel + input2 * (1 - sel)
170	            // sel is bool (0 or 1), we use Select API
171	            // For float: reinterpret and use select
172	            AscendC::LocalTensor<float> in1Fp32 = input1Local_.template ReinterpretCast<float>();
173	            AscendC::LocalTensor<float> in2Fp32 = input2Local_.template ReinterpretCast<float>();
174	
175	            // Use Select: selLocal_ as mask, pick from in1Fp32 or in2Fp32
176	            // sel is uint8 (0/1), we need to use it as comparison mask
177	            // First, create a float mask from sel
178	            AscendC::Cast(fp32Local_, selLocal_, AscendC::RoundMode::CAST_NONE, N_);
179	            // fp32Local_ now contains 0.0 or 1.0
180	            // out = in1 * mask + in2 * (1 - mask)
181	            // = in2 + (in1 - in2) * mask
182	            AscendC::Sub(fp32Local_, in1Fp32, in2Fp32, N_);
183	            AscendC::Mul(fp32Local_, fp32Local_, selLocal_.template ReinterpretCast<float>(), N_);
184	            AscendC::Add(fp32Local_, fp32Local_, in2Fp32, N_);
185	        } else {
186	            // Cast to fp32 first
187	            AscendC::LocalTensor<float> in1Fp32 = castBuf_.Get<float>();
188	            AscendC::LocalTensor<float> in2Fp32 = castBuf_.Get<float>();
189	            // Use different offset for in2Fp32 to avoid overlap
190	            // Actually castBuf_ is only N_ * sizeof(float), need to be careful
191	            // Let's use fp32Local_ as temp and reuse
192	            AscendC::Cast(fp32Local_, input1Local_, AscendC::RoundMode::CAST_NONE, N_);
193	            // Copy to a safe location - use maxLocal_ as temp storage
194	            AscendC::DataCopy(in1Fp32, fp32Local_, N_);
195	            AscendC::Cast(fp32Local_, input2Local_, AscendC::RoundMode::CAST_NONE, N_);
196	            AscendC::DataCopy(in2Fp32, fp32Local_, N_);
197	
198	            // Now compute select in fp32
199	            // Cast sel to float mask
200	            AscendC::Cast(fp32Local_, selLocal_, AscendC::RoundMode::CAST_NONE, N_);
201	            // fp32Local_ = in1Fp32 - in2Fp32
202	            AscendC::Sub(fp32Local_, in1Fp32, in2Fp32, N_);
203	            // fp32Local_ = fp32Local_ * mask
204	            // Need mask as float - reuse in1Fp32 area after
205	            AscendC::LocalTensor<float> maskFp32 = castBuf_.Get<float>();
206	            AscendC::Cast(maskFp32, selLocal_, AscendC::RoundMode::CAST_NONE, N_);
207	            AscendC::Mul(fp32Local_, fp32Local_, maskFp32, N_);
208	            // fp32Local_ = fp32Local_ + in2Fp32
209	            AscendC::Add(fp32Local_, fp32Local_, in2Fp32, N_);
210	        }
211	
212	        // Step 2: ReduceMax over N
213	        AscendC::ReduceMax<float>(maxLocal_, fp32Local_, reduceTmpLocal_, N_);
214	        AscendC::PipeBarrier<PIPE_ALL>();
215	        float maxVal = maxLocal_.GetValue(0);
216	        AscendC::PipeBarrier<PIPE_ALL>();
217	
218	        // Step 3: Sub = fp32Local_ - maxVal
219	        AscendC::Adds(fp32Local_, fp32Local_, -maxVal, N_);
220	
221	        // Step 4: Exp
222	        AscendC::Exp(fp32Local_, fp32Local_, N_);
223	
224	        // Step 5: ReduceSum over N
225	        AscendC::ReduceSum<float>(sumLocal_, fp32Local_, reduceTmpLocal_, N_);
226	        AscendC::PipeBarrier<PIPE_ALL>();
227	        float sumVal = sumLocal_.GetValue(0);
228	        AscendC::PipeBarrier<PIPE_ALL>();
229	
230	        // Step 6: Div = fp32Local_ / sumVal
231	        float invSum = 1.0f / sumVal;
232	        AscendC::Muls(fp32Local_, fp32Local_, invSum, N_);
233	
234	        // Step 7: Cast back to original dtype and write to output
235	        if constexpr (std::is_same_v<dataType, float>) {
236	            AscendC::LocalTensor<float> outFp32 = outputLocal_.template ReinterpretCast<float>();
237	            AscendC::DataCopy(outFp32, fp32Local_, N_);
238	        } else {
239	            AscendC::Cast(outputLocal_, fp32Local_, AscendC::RoundMode::CAST_ROUND, N_);
240	        }
241	
242	        // Free inputs
243	        selQueue_.FreeTensor(selLocal_);
244	        input1Queue_.FreeTensor(input1Local_);
245	        input2Queue_.FreeTensor(input2Local_);
246	        // EnQue output
247	        outputQueue_.EnQue(outputLocal_);
248	    }
249	
250	    __aicore__ inline void CopyOut(uint64_t rowOffset)
251	    {
252	        outputLocal_ = outputQueue_.DeQue<dataType>();
253	        StoreUbToGm(outputGM_[rowOffset], outputLocal_, static_cast<uint32_t>(N_));
254	        outputQueue_.FreeTensor(outputLocal_);
255	    }
256	
257	private:
258	    int32_t B_ = 0;
259	    int32_t M_ = 0;
260	    int32_t N_ = 0;
261	    int32_t totalRows_ = 0;
262	    int32_t usedCoreNum_ = 0;
263	    int32_t tasksPerCore_ = 0;
264	
265	    TilingData tiling_;
266	    AscendC::TPipe pipe_;
267	
268	    AscendC::GlobalTensor<uint8_t> selGM_;
269	    AscendC::GlobalTensor<dataType> input1GM_;
270	    AscendC::GlobalTensor<dataType> input2GM_;
271	    AscendC::GlobalTensor<dataType> outputGM_;
272	
273	    // Queues
274	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> selQueue_;
275	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> input1Queue_;
276	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> input2Queue_;
277	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outputQueue_;
278	
279	    // Buffers
280	    AscendC::TBuf<AscendC::TPosition::VECCALC> fp32Buf_;
281	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceTmpBuf_;
282	    AscendC::TBuf<AscendC::TPosition::VECCALC> scalarBuf_;
283	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;
284	
285	    // Local tensors
286	    AscendC::LocalTensor<uint8_t> selLocal_;
287	    AscendC::LocalTensor<dataType> input1Local_;
288	    AscendC::LocalTensor<dataType> input2Local_;
289	    AscendC::LocalTensor<dataType> outputLocal_;
290	    AscendC::LocalTensor<float> fp32Local_;
291	    AscendC::LocalTensor<uint8_t> reduceTmpLocal_;
292	    AscendC::LocalTensor<float> maxLocal_;
293	    AscendC::LocalTensor<float> sumLocal_;
294	};
